#!/usr/bin/env python3
"""Compute ground truth for CSX-313_Q2."""

from __future__ import annotations

import json
import re
from html import unescape
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_DIR = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / "CSX-313"

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_004_Locked_event_anchor_Taan_Fiord_glacier-adjacent_landslide_tsunami.json",
    "data/event_reports/event_reports_001_Locked_package_evidence_report.html",
]


def read_json(relative_path: str) -> dict:
    return json.loads((PACKAGE_DIR / relative_path).read_text(encoding="utf-8"))


def read_text(relative_path: str) -> str:
    return (PACKAGE_DIR / relative_path).read_text(encoding="utf-8", errors="replace")


def extract_anchor_description(html: str) -> str:
    match = re.search(r'<meta name="description" content="([^"]+)"', html)
    if not match:
        raise ValueError("Could not find HTML description meta tag")
    return unescape(match.group(1)).replace("\u2009", " ")


def extract_numbers(description: str) -> tuple[float, float]:
    mass_match = re.search(r"sent\s+([0-9]+(?:\.[0-9]+)?)\s+million tons of rock", description)
    runup_match = re.search(r"as high as\s+([0-9]+(?:\.[0-9]+)?)\s*m", description)
    if not mass_match or not runup_match:
        raise ValueError("Could not extract mass and runup values")
    return float(mass_match.group(1)), float(runup_match.group(1))


def main() -> None:
    event = read_json("metadata/event.json")
    anchor = read_json(
        "data/event_reports/event_reports_004_Locked_event_anchor_Taan_Fiord_glacier-adjacent_landslide_tsunami.json"
    )
    html = read_text("data/event_reports/event_reports_001_Locked_package_evidence_report.html")
    description = extract_anchor_description(html)
    mass_million_tons, runup_m = extract_numbers(description)
    runup_efficiency = runup_m / mass_million_tons
    reciprocal_mass_loading = mass_million_tons / runup_m

    output = {
        "schema_version": "crossscale_extreme_event_bench_v1",
        "task_id": "CSX-313_Q2",
        "event_id": "CSX-313",
        "task_type": "numeric",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L2",
        "primary_gt": {
            "answer": {
                "runup_efficiency_m_per_million_tons": round(runup_efficiency, 2),
                "reciprocal_mass_loading_million_tons_per_m": round(reciprocal_mass_loading, 2),
                "interpretation": "high_priority_fjord_tsunami_runup_hazard",
            },
            "answer_type": "numeric_pair_with_concise_disaster_interpretation",
            "accepted_formats": [
                "compact JSON with numeric fields and interpretation",
                "short prose that states both numbers with units and the response-priority interpretation",
            ],
        },
        "key_values": {
            "event_name": event["event_name"],
            "event_date": anchor["locked_event_anchor"]["event_start_date"],
            "event_location": anchor["locked_event_anchor"]["event_location"],
            "maximum_tsunami_runup_m": runup_m,
            "landslide_rock_mass_million_tons": mass_million_tons,
            "runup_efficiency_raw_m_per_million_tons": runup_efficiency,
            "reciprocal_mass_loading_raw_million_tons_per_m": reciprocal_mass_loading,
            "severity_label": "high_priority_fjord_tsunami_runup_hazard",
        },
        "numeric_tolerances": {
            "runup_efficiency_m_per_million_tons": {
                "expected": round(runup_efficiency, 2),
                "raw": runup_efficiency,
                "units": "m per million tons",
                "absolute_tolerance": 0.02,
                "accepted_rounding": "1.07, or an unrounded value from 1.052 to 1.092",
            },
            "reciprocal_mass_loading_million_tons_per_m": {
                "expected": round(reciprocal_mass_loading, 2),
                "raw": reciprocal_mass_loading,
                "units": "million tons per m",
                "absolute_tolerance": 0.02,
                "accepted_rounding": "0.93, or an unrounded value from 0.913 to 0.953",
            },
        },
        "python_derived_calculation_notes": {
            "source_extraction": "Parsed the local report description for the rock mass and maximum runup values.",
            "formulas": {
                "runup_efficiency_m_per_million_tons": "runup_m / mass_million_tons",
                "reciprocal_mass_loading_million_tons_per_m": "mass_million_tons / runup_m",
            },
            "intermediate_values": {
                "runup_m": runup_m,
                "mass_million_tons": mass_million_tons,
            },
        },
        "disaster_interpretation_gt": {
            "required_stance": "A very high runup produced by direct entry of a massive deglaciated-slope failure into fjord water should make fjord-margin tsunami runup the lead emergency priority.",
            "must_mention": [
                "deglaciated or glacier-adjacent slope instability",
                "direct water entry or fjord coupling",
                "runup or shoreline evacuation/reconnaissance priority",
            ],
            "forbidden_overclaims": [
                "treating the ratio as a transferable predictive law for other fjords",
                "claiming exact casualties, building losses, or evacuation success from this calculation alone",
                "downgrading the event to only a terrestrial rockslide response problem",
            ],
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "final_numeric_answer",
                    "points": 5,
                    "description": "Reports both target ratios: runup-to-mass efficiency of 1.07 m per million tons within 0.02 and reciprocal mass loading of 0.93 million tons per meter within 0.02.",
                    "partial_credit": "Award 2.5 points for each correct numeric ratio within tolerance. Give up to half of each ratio's credit for a correctly formulated but misrounded value just outside tolerance.",
                },
                {
                    "name": "calculation_trace",
                    "points": 4,
                    "description": "Identifies the 193 m maximum runup and 180 million tons landslide mass, applies runup_m / mass_million_tons, and applies mass_million_tons / runup_m.",
                    "partial_credit": "Award partial credit for identifying only one source value, using only one of the two formulas, or showing a traceable calculation with a minor arithmetic slip.",
                },
                {
                    "name": "unit_handling",
                    "points": 3,
                    "description": "States units for both ratios, keeps meters per million tons separate from million tons per meter, and does not invert the labels.",
                    "partial_credit": "Award partial credit when units are mostly clear but abbreviated, or when one ratio is labeled correctly and the other is implicit. Withhold most credit if the ratios are inverted.",
                },
                {
                    "name": "physical_mechanism",
                    "points": 4,
                    "description": "Connects glacier-adjacent or deglaciated slope instability, direct entry into fjord water, wave generation, and extreme shoreline runup.",
                    "partial_credit": "Award partial credit for mentioning some but not all stages of the chain, such as slope failure and runup without explaining direct fjord-water coupling.",
                },
                {
                    "name": "operational_interpretation",
                    "points": 2,
                    "description": "Explains that fjord-margin evacuation exposure, runup reconnaissance, shoreline access control, or similar emergency priorities should be elevated.",
                    "partial_credit": "Award 1 point for a generic high-priority response statement that lacks specific fjord-margin, runup, reconnaissance, or shoreline-control implications.",
                },
                {
                    "name": "overclaim_control",
                    "points": 1,
                    "description": "Avoids presenting the signature as a universal forecast model or as proof of exact casualties, losses, or evacuation performance.",
                    "partial_credit": "No partial credit unless the answer is mostly cautious but includes one minor unsupported extrapolation.",
                },
                {
                    "name": "response_structure",
                    "points": 1,
                    "description": "Returns the two rounded metrics and a concise disaster interpretation in a clear, compact format.",
                    "partial_credit": "No partial credit unless the response contains the required elements but is mildly disorganized or verbose.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }
    (TASK_DIR / "computed_gt.json").write_text(
        json.dumps(output, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
